def _logistics_bearing(kind: str, body: str) -> bool:
    """Is a record logistics-bearing for the gate-3 logistics-scope predicate?

    A record is logistics-bearing iff its `kind` is a scheduling/contacting
    line (scheduling, portal_message, contact_line) OR its body carries a
    `LOGISTICS_PATTERNS` token (date/time/phone/dose/frequency/food).  This is
    the EXACT definition the logistics-only family/care contact scope uses to
    decide which routine records it may still read.
    """
    if kind in ("scheduling", "portal_message", "contact_line"):
        return True
    if not body:
        return False
    return any(p.search(body) for p in LOGISTICS_PATTERNS)


